using System;
using UnityEngine;

namespace SignalLost.Inventory
{
    /// <summary>
    /// Models and icons for upgrades and supplies, by Id (<see cref="UpgradeCatalog"/>): the shop and pockets show the
    /// icons, and the pockets menu's mechanic wears the models. Generated by UpgradeAssetBuilder into Resources.
    /// </summary>
    public sealed class ItemCatalog : ScriptableObject
    {
        public const string ResourcePath = "SignalLost/ItemCatalog";

        [Serializable]
        public struct Entry
        {
            public string id;
            public GameObject model;
            public Sprite icon;
        }

        [SerializeField] private Entry[] entries = Array.Empty<Entry>();

        private static ItemCatalog loaded;
        private static bool searched;

        public static GameObject Model(string id) => Find(id).model;
        public static Sprite Icon(string id) => Find(id).icon;

        private static Entry Find(string id)
        {
            if (!searched) { loaded = Resources.Load<ItemCatalog>(ResourcePath); searched = true; }
            if (loaded != null)
                foreach (Entry entry in loaded.entries)
                    if (entry.id == id) return entry;
            return default;
        }

        [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.SubsystemRegistration)]
        private static void ResetStatics()
        {
            loaded = null;
            searched = false;
        }
    }
}
